-- STEP 188 (PRECHECK, run first, changes nothing): 0436 Release audit fixes: an import is marked while it is written; Sawyer Steele's cut-off copy gets its missing days; a client never reads an organization program's days; the team sheet never saves into one; one fixed search_path
--
-- !! This adds programs.importing (default false; the app marks an import with it while the days are being written, and nothing copies it until it is finished). It then copies into Sawyer Steele's copy of “Big Sauce but still little sauce” the 20 days it is missing (week 5 day 6 and weeks 6 to 8), with their exercises and sets, the way a copy is always made; nothing the copy already has is changed or deleted, and Sawyer's logged session stays on its workout. The paste checks first that the copy still has exactly its 29 days and the program is exactly what the import wrote, and afterwards that the copy has every day and exercise of the program, or nothing is kept. It also adds ONE condition to is_ai_draft_program and ONE to is_ai_draft_workout (a client never reads an organization program's days, exercises, sets, notes or progression rules; coaches read as before), and ONE to team_sheet_save (never into an organization program's workout); the paste checks each live function is exactly the expected one, and stops if not. Last, training_partners_cross_org_enabled gets an empty search_path.
--
-- Paste into the Supabase SQL editor and run. Every row must say ok = true.
-- If any row says false: do NOT run the apply file. Copy the result table and send it back.
select check_name, ok
from (
  values
    ('0436 is not already applied (programs has no importing yet)',
      not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'programs' and column_name = 'importing')),
    ('Sawyer''s copy is there: Sawyer''s, active, not archived, made from the program',
      (select count(*) from public.programs where id = '84d908e7-7b92-4143-a1da-b810f120bce6' and athlete_id = '1ba45158-a419-49d4-916a-4807725677ac' and group_id = '11111111-2222-3333-4444-555555555555' and is_active and archived_at is null and source_program_id = '39dc737c-1f7e-43ff-a414-68dda082a1ed') = 1),
    ('Sawyer''s copy still has exactly its 29 days, by id (160 exercises, 435 sets)',
      (select count(*) from public.workouts where program_id = '84d908e7-7b92-4143-a1da-b810f120bce6') = 29 and (select count(*) from public.workouts where program_id = '84d908e7-7b92-4143-a1da-b810f120bce6' and id in ('b01e0b7c-efca-4648-b68c-1b2a452daecc', '98ddaaef-ae1e-4916-a549-e41e6c6e7e64', '4ebeee75-f643-467b-8fce-778127369de4', '6ae754cb-49be-476a-b39b-98d80ad7c561', '5e4c4c3f-d42d-4071-a065-b0cba433a377', '502722c9-958c-4ce4-a34f-2439d9f06b92', '21dde757-d49d-49ee-be95-cece14fcb339', '51607667-91d3-400a-97ba-bc46d28fa063', '440dd296-d06b-4f84-a62b-e367b28ccade', 'a67f4957-d98a-46a6-a6d6-bc2a381ab447', '3849fb9f-1372-49f0-8b41-b84b66c461ef', '6f926d43-4f42-416f-8c10-0fb6849a222b', '8a31b6bc-a000-45f4-b18b-6fc33fe7f8cb', '0c14ed22-2911-40d9-9a55-bf5e0bad2de3', 'd3f39a2d-90cc-40c5-b7d5-8ae089566ba9', 'd7ea11c9-5dc0-4633-ba6d-46ef4df7921d', '08d2ff98-df09-445f-8118-712335bd6f4c', '79c2dc10-483a-4d2d-a6f5-750b0dc83136', 'd43b7570-d29c-48bc-9bbd-96bb8289dace', 'b2f2ccc0-8b57-4428-af4b-8da6b12de23f', 'e6421ad9-9c67-45d1-a149-9a2aa6a7a04b', '7737ec44-cf76-4a78-94f7-22e0c639fffa', '960628b5-a92f-450d-b6d8-efb68c1e28da', 'b577864d-eadc-42eb-9506-7dc1c7c15ff5', '86159c0f-bde8-45cf-ac25-51d967943b48', '4dc1fbeb-9dfb-47f8-941a-b9d1e24d4c33', '50e7172e-360f-4b65-8bdb-bd68f89e3b9b', 'cffa5008-258c-43c5-b41d-c69236dacba4', '94ecb5f7-c640-402e-b54f-09a3bbd0962f')) = 29 and (select count(*) from public.group_workout_exercises g join public.workouts w on w.id = g.workout_id where w.program_id = '84d908e7-7b92-4143-a1da-b810f120bce6') = 160 and (select count(*) from public.group_workout_exercise_sets s join public.group_workout_exercises g on g.id = s.group_workout_exercise_id join public.workouts w on w.id = g.workout_id where w.program_id = '84d908e7-7b92-4143-a1da-b810f120bce6') = 435),
    ('the program is exactly what the import wrote (49 days, 277 exercises, 714 sets, no notes or rules, the last day at 21:44:57, every day, exercise and set unchanged)',
      (select count(*) from public.workouts where program_id = '39dc737c-1f7e-43ff-a414-68dda082a1ed') = 49 and (select count(*) from public.group_workout_exercises g join public.workouts w on w.id = g.workout_id where w.program_id = '39dc737c-1f7e-43ff-a414-68dda082a1ed') = 277 and (select count(*) from public.group_workout_exercise_sets s join public.group_workout_exercises g on g.id = s.group_workout_exercise_id join public.workouts w on w.id = g.workout_id where w.program_id = '39dc737c-1f7e-43ff-a414-68dda082a1ed') = 714 and (select count(*) from public.workout_notes n join public.workouts w on w.id = n.workout_id where w.program_id = '39dc737c-1f7e-43ff-a414-68dda082a1ed') = 0 and (select count(*) from public.exercise_progressions where program_id in ('39dc737c-1f7e-43ff-a414-68dda082a1ed', '84d908e7-7b92-4143-a1da-b810f120bce6')) = 0 and (select max(created_at) from public.workouts where program_id = '39dc737c-1f7e-43ff-a414-68dda082a1ed') = '2026-10-26 21:44:57.220386+00'::timestamptz and (select md5(coalesce(string_agg(r, chr(10) order by r), '')) from (select concat_ws('|', w.week_number, w.day_index, w.title, w.notes, w.scheduled_date, e.exercise_order, e.exercise_name, e.tracked_fields::text, e.notes, e.display_name, e.movement_pattern_id, e.is_slot, e.slot_side, e.slot_tier, s.set_order, s.target_reps, s.target_weight, s.target_rpe, s.target_rir, s.target_tempo, s.target_time_seconds, s.target_height, s.target_distance, s.rep_min, s.rep_max, s.target_rest_seconds, s.target_rest_max_seconds, s.target_pace, s.set_type) as r from public.workouts w left join public.group_workout_exercises e on e.workout_id = w.id left join public.group_workout_exercise_sets s on s.group_workout_exercise_id = e.id where w.program_id = '39dc737c-1f7e-43ff-a414-68dda082a1ed') as x) = 'faee2d50f38600beeb855a7710f182da'),
    ('Sawyer''s one logged session on the copy is on week 1 day 1',
      (select count(*) from public.athlete_sessions s join public.workouts w on w.id = s.workout_id where w.program_id = '84d908e7-7b92-4143-a1da-b810f120bce6') = 1 and exists (select 1 from public.athlete_sessions where id = '072e7dd6-82eb-4550-9ca0-d4f32b6cd806' and workout_id = 'b01e0b7c-efca-4648-b68c-1b2a452daecc')),
    ('is_ai_draft_program is exactly the expected function',
      coalesce((select md5(replace(pg_get_functiondef(p.oid), chr(13), '')) = '6b77132524936e6cadb7ef4758a8232c' from pg_proc p where p.oid = to_regprocedure('public.is_ai_draft_program(uuid)')), false)),
    ('is_ai_draft_workout is exactly the expected function',
      coalesce((select md5(replace(pg_get_functiondef(p.oid), chr(13), '')) = '05cd3cad64ff751a2dbbafbdc807ab34' from pg_proc p where p.oid = to_regprocedure('public.is_ai_draft_workout(uuid)')), false)),
    ('team_sheet_save is exactly the expected function (0419)',
      coalesce((select md5(replace(pg_get_functiondef(p.oid), chr(13), '')) = '3947181f746122f948651fb2e1180cf0' from pg_proc p where p.oid = to_regprocedure('public.team_sheet_save(uuid, text, jsonb, boolean, uuid, boolean)')), false)),
    ('training_partners_cross_org_enabled is there',
      to_regprocedure('public.training_partners_cross_org_enabled()') is not null)
) as checks(check_name, ok);
